import os
from pathlib import Path

from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.epcsim.exceptions import ConfigurationFileException  # type: ignore
from taf.ul.sc.perf.collectors.collect_tti import move_and_zip_tti_directories
from taf.ul.sc.perf.util.logger import log_info_to_console

class LogsCollector(object):
    def __init__(self, output_dir=None, config_log_dir=None, debug_log_dir=None, report_log_dir=None):
        self.output_dir = output_dir if output_dir else str(tc.output_dir)
        self.config_log_dir = config_log_dir if config_log_dir else os.path.join(self.output_dir, 'config')
        self.debug_log_dir = debug_log_dir if debug_log_dir else os.path.join(self.output_dir, 'debug')
        self.report_log_dir = report_log_dir if report_log_dir else os.path.join(self.output_dir, 'report')

    def collect_bts_logs(self):
        for bts in tc.required_btss():
            self.set_collection_parameters(bts)
        if tc.is_feature_enabled("collect_tti_traces"):
            dir_pattern = '{}*'.format(tc.run_params['collect_tti_traces']['tti_alias'])
            tti_output_dir = os.path.join(self.debug_log_dir, perf.tl.main_bts.name, 'tti')
            move_and_zip_tti_directories(log_dir=self.output_dir, destination_dir=tti_output_dir,
                                         dir_pattern=dir_pattern)

    def set_collection_parameters(self, bts):
        debug_bts_dir = os.path.join(self.debug_log_dir, bts.name)
        config_bts_dir = os.path.join(self.config_log_dir, bts.name)
        report_bts_dir = os.path.join(self.report_log_dir, bts.name)
        if tc.is_feature_enabled("logs_collecting->bts_debug_logs"):
            bts.collect_snapshot(log_dir=debug_bts_dir)
            bts.collect_additional_logs(log_dir=debug_bts_dir)
        if tc.is_feature_enabled("logs_collecting->bts_configuration"):
            bts.collect_configuration(log_dir=config_bts_dir)
        if tc.is_feature_enabled("collect_bts_stats"):
            if tc.run_params['collect_bts_stats']['type'] == 'rtpm':
                bts.collect_pm_files(log_dir=os.path.join(report_bts_dir, 'pmstats'), log_level='info')
                bts.ems.ws.collect_rtpm_data_file(destination_dir=os.path.join(report_bts_dir, 'pmstats'))
            else:
                bts.collect_pm_files(log_dir=os.path.join(report_bts_dir, 'pmstats'))
            bts.collect_rise_pm_data(log_dir=os.path.join(report_bts_dir, 'pmstats'))

    def collect_ue_logs(self):
        config_ue_dir = os.path.join(self.config_log_dir, perf.tl.ue.name)
        debug_ue_dir = os.path.join(self.debug_log_dir, perf.tl.ue.name)
        report_ue_dir = os.path.join(self.report_log_dir, perf.tl.ue.name)

        if tc.is_feature_enabled("logs_collecting->ue_debug_logs"):
            perf.tl.ue.collect_debug_logs(log_dir=debug_ue_dir)
        if tc.is_feature_enabled("logs_collecting->ue_configuration"):
            perf.tl.ue.collect_configuration(log_dir=config_ue_dir)

        perf.tl.ue.collect_report(log_dir=report_ue_dir)
        # TODO: add flag in params to indicate if data-collector is used. Maybe test validation?
        # Send data from scenario execution to data-collector folder
        perf.tl.ue.collect_report(log_dir=Path.home() / "collector" / "monitoring" / "cus")
        perf.tl.ue.started_scenarios = []  # WA - better clear at the beginning of the test - Initial Actions

    def collect_core_simulator_logs(self):
        destination_path = os.path.join(self.config_log_dir, perf.tl.core.name)
        log_info_to_console(msg=f"Collecting core simulator logs from path: {destination_path}", banner=True)
        try:
            if tc.is_feature_enabled("core_preparation->reconfigure"):
                configuration_file = tc.run_params['core_preparation']['reconfigure']['config_file']
                configuration_file = get_absolute_path(configuration_file)
                direction, file_name = os.path.split(configuration_file)
                perf.tl.core.collect_configuration(log_dir=destination_path, config_file_dir=direction)
            else:
                perf.tl.core.collect_configuration(log_dir=destination_path)
        except ConfigurationFileException:
            self._get_epcsim_config_from_git(destination_path=destination_path)

    def _get_epcsim_config_from_git(self, destination_path):
        perf.tl.unix_local.make_directory(destination_path)

        config_file_path = get_absolute_path(tc.run_params['core_preparation']['reconfigure']['config_file'])
        perf.tl.unix_local.copy_file(config_file_path, destination_path)

        require_files = tc.run_params['core_preparation']['reconfigure']['require_files']
        for file_name in require_files:
            perf.tl.unix_local.copy_file(get_absolute_path(file_name), destination_path)
